// Simple arcade game based on IDEA.md
// Canvas with id="game"

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');

  // Set canvas size to fill viewport
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  // Ship definition
  const ship = {
    width: 40,
    height: 20,
    x: canvas.width / 2 - 20,
    y: canvas.height - 30,
    speed: 5,
    dx: 0,
    draw() {
      ctx.fillStyle = '#00f';
      ctx.fillRect(this.x, this.y, this.width, this.height);
    },
    update() {
      this.x += this.dx;
      // keep inside bounds
      if (this.x < 0) this.x = 0;
      if (this.x + this.width > canvas.width) this.x = canvas.width - this.width;
    },
  };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function handleInput() {
    ship.dx = 0;
    if (keys['ArrowLeft'] || keys['a']) ship.dx = -ship.speed;
    if (keys['ArrowRight'] || keys['d']) ship.dx = ship.speed;
  }

  // Debris definition
  const debris = [];
  const debrisSize = 20;
  const spawnInterval = 1000; // ms
  let lastSpawn = 0;

  function spawnDebris() {
    const x = Math.random() * (canvas.width - debrisSize);
    debris.push({ x, y: -debrisSize, size: debrisSize, speed: 2 + Math.random() * 3 });
  }

  function updateDebris(delta) {
    for (let i = debris.length - 1; i >= 0; i--) {
      const d = debris[i];
      d.y += d.speed;
      if (d.y > canvas.height) debris.splice(i, 1);
    }
    // spawn new debris based on time
    if (Date.now() - lastSpawn > spawnInterval) {
      spawnDebris();
      lastSpawn = Date.now();
    }
  }

  function drawDebris() {
    ctx.fillStyle = '#888';
    debris.forEach(d => ctx.fillRect(d.x, d.y, d.size, d.size));
  }

  // Collision detection
  function checkCollision() {
    for (const d of debris) {
      if (
        ship.x < d.x + d.size &&
        ship.x + ship.width > d.x &&
        ship.y < d.y + d.size &&
        ship.y + ship.height > d.y
      ) {
        return true;
      }
    }
    return false;
  }

  // Score
  let startTime = Date.now();
  let gameOver = false;

  function drawScore() {
    const seconds = Math.floor((Date.now() - startTime) / 1000);
    ctx.fillStyle = '#000';
    ctx.font = '20px sans-serif';
    ctx.fillText(`Score: ${seconds}s`, 10, 30);
  }

  // Main loop
  let lastTime = 0;
  function loop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const delta = timestamp - lastTime;
    lastTime = timestamp;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    handleInput();
    ship.update();
    ship.draw();

    updateDebris(delta);
    drawDebris();

    drawScore();

    if (checkCollision()) {
      gameOver = true;
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
      return;
    }

    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
